    if (!side) return g.sold[id] ? null : { m: 'excited', l: 'Free agent', q: 'Still available. Sign me in the transfer window!' };
    if (u.stage !== 'play') return { m: 'nervous', l: 'Bracing', q: 'Here comes the twist…' };
    const r = this.pmHire(id); if (!r) return null;
