      if (C.synergy[s2].raw >= C.synergy.cap) add('link', 'Synergy master', 'Synergy cap reached');
      if (C.twist[s2].penalty === 0) add('shield', 'Twist-proof', 'No damage from the twist');
      if (B.bargains.length >= 2) add('coin', 'Bargain hunter', B.bargains.length + ' bargains');
      if (C.functions[s2].missing.length === 0) add('check', 'Full house', 'Every core function hired');
